from pathlib import Path
import json
p=Path(__file__).resolve().parents[1];npcs=json.loads((p/'data/npcs.json').read_text());profiles=json.loads((p/'data/dialogue.json').read_text())
identity={'mara':'Mara. If you came for charity, try the chapel. If you came for supplies, we can talk.','brann':'Brann. Blacksmith, grave digger when needed, and a poor liar. Your blade looks tired.','sister':'Elowen. I tend the sick and keep the chapel open. Names are easier to mend than memories.','nell':'Nell, keeper of the Last Hearth. Sit near the fire. It still remembers how to be kind.','ilya':'Captain Ilya. There is no army left to command. Only a square worth defending.','osric':'Osric. I once called myself a shepherd of souls. These days I mostly lose the flock.','tovin':'Tovin. My brother used to introduce us both. I still wait for him to do it.','vesper':'You may call me Vesper. The name you need is your own. We will come to that.'}
rumors={'mara':'Brann lets his forge burn all night. Says it keeps the dead away. I think he simply cannot bear the dark.','brann':'Mara knows which roads are still safe. She pretends she does not care who returns from them.','sister':'Osric has been leaving bread at empty graves. I do not ask whether it is prayer or apology.','nell':'Ilya visits the well at dawn. Eight names, spoken softly. Never a ninth.','ilya':'Vesper arrived before the curse. I have never seen anyone remember his arrival.','osric':'Elowen knows the keeper’s face. Ask gently. Some truths look too much like wounds.','tovin':'Nell keeps my brother’s seat empty. I wish she would stop. I wish she never would.','vesper':'The healer remembers what the innkeeper repeats in dreams. Between them, a whole kingdom survives.'}
history={'mara':'The town grew around the road and its tollhouse. Now the road brings nobody, and the toll is paid in memories.','brann':'The king wanted iron from these hills. Hollowmere fed his armies until his armies came home hollow.','sister':'There was a spring under this chapel. Pilgrims came for its water. The first bell was meant to guide them home.','nell':'Miners, pilgrims, merchants. Everyone passed through the Last Hearth. I kept their songs; the Veil took their names.','ilya':'We defended a crossing, then a road, then a village. The kingdom shrank until it fit inside this square.','osric':'The bells were blessed before they were weapons. I signed the prayer that hung beside the first one.','tovin':'It was a small place even then. The forest sounded ordinary. That is what I miss most.','vesper':'Hollowmere is where endings gather. Kingdoms fall elsewhere; here we learn what survived them.'}
king={'mara':'The king paid his debts with promises. You cannot eat a promise.','brann':'His crest was stamped on every sword. None of those swords could cut a curse.','sister':'He wanted to keep everyone safe. Fear makes that wish dangerous.','nell':'There is still a room upstairs bearing his crest. Nobody sleeps soundly in it.','ilya':'I have not seen him since the western bridge. I no longer trust reports of his death.','osric':'We mistook obedience for faith. I cannot tell you which of us was more afraid.','tovin':'Kings were stories adults told. My brother was real.','vesper':'Ask the shrine what the king asked the bell to forget.'}
why={'mara':'Because leaving means trusting a road. Here I can at least see who owes me.','brann':'Someone must keep their tools sharp. Someone must be here when they return.','sister':'The sick cannot leave. Neither can I.','nell':'If the last fire goes out, then we truly have no home.','ilya':'There are still people behind me. That is reason enough.','osric':'I helped invite this silence. Walking away would be another prayer without meaning.','tovin':'If my brother ever finds his way back, someone must answer the door.','vesper':'Because you would wake here again. I wanted this time to be different.'}
post={'mara':'You silenced it? I will give you fair prices today. Do not make me regret saying that.','brann':'The anvil sounds louder without that damned bell. Good work, wanderer.','sister':'The fever has broken in two houses. Whatever awaits at the shrine, remember this mercy.','nell':'For the first night in years, the sleepers did not scream. Stay for a while.','ilya':'The bell is silent. You gave us a morning I thought we had lost. The shrine is open.','osric':'I can hear my own prayers again. They sound smaller, but more honest.','tovin':'I dreamed of my brother without the forest behind him. Thank you.','vesper':'The guardian is gone. The shrine can no longer hide your choice from you.'}
def choice(text,next='root',action=None,condition=None):
 d={'text':text,'next':next}
 if action:d['action']=action
 if condition:d['condition']=condition
 return d
alltrees={}
quests={'brann':'iron','sister':'herbs','tovin':'charm','ilya':'bell'}
for id,npc in npcs.items():
 root=[choice('Who are you?','identity'),choice('What is your story?','past'),choice('Tell me about Hollowmere.','town'),choice('What do you know of the Veil?','veil'),choice('I heard the bell has fallen silent.','boss',condition={'flag':'boss'})]
 if id in quests:root.append(choice('Have any work for me?','work'))
 services={'mara':[choice('Show me your wares.',action={'kind':'shop'}),choice('I would like to sell something.',action={'kind':'sell'})],'brann':[choice('Can you improve my weapon?',action={'kind':'upgrade'})],'sister':[choice('Can you heal me?',action={'kind':'heal'}),choice('Where can I buy medicine?','medicine')],'nell':[choice('May I rest here?',action={'kind':'rest'})]}
 root+=services.get(id,[])+[choice('Goodbye.',action={'kind':'goodbye'})]
 common=[choice('What happened to the king?','king'),choice('Why did you stay?','stay'),choice('What do you hear about the others?','rumors'),choice('Back.','root')]
 nodes={'root':{'text':npc['line'],'variants':[{'condition':{'flag':'boss'},'text':post[id]},{'condition':{'memory':id+'_insult'},'text':'I have not forgotten your cruelty. Speak honestly this time.'}],'choices':root},'identity':{'text':identity[id],'choices':[choice('What is your story?','past'),choice('Back.')]},'past':{'text':profiles[id]['past'],'choices':common},'town':{'text':history[id],'choices':[choice('What happened to the king?','king'),choice('Tell me a local rumor.','rumors'),choice('What dangers lie nearby?','dangers'),choice('Back.')]},'king':{'text':king[id],'choices':[choice('Why did you stay?','stay'),choice('Back.')]},'stay':{'text':why[id],'choices':[choice('Back.')]},'rumors':{'text':rumors[id],'choices':[choice('What dangers lie nearby?','dangers'),choice('Back.')]},'veil':{'text':profiles[id]['veil'],'choices':[choice('What waits in the crypt?','bell'),choice('What do you know of the shrine?','shrine'),choice('Back.')]},'bell':{'text':'The Bellkeeper marks the ground before its blows. Leave the circle, then strike as it recovers. No armor makes standing beneath a falling bell wise.','choices':[choice('How do I reach it?','dangers'),choice('Back.')]},'dangers':{'text':'The sentinel guards the eastern forest gate and carries the crypt sigil. The southwest hollow belongs to a lost hound. Stay on the paths until you can read their tracks.','choices':[choice('And the Bellkeeper?','bell'),choice('Back.')]},'shrine':{'text':'Beyond the guardian lies a place the Veil could not erase. Its crystal remembers who rang the first bell.','choices':[choice('Back.')]},'boss':{'text':post[id],'choices':[choice('Tell me about the shrine.','shrine'),choice('Back.')]},'medicine':{'text':'Mara sells draughts by the square. The blue crystals restore your strength for free. Do not mistake endurance for wisdom.','choices':[choice('Can you heal me?',action={'kind':'heal'}),choice('Back.')]}}
 if id in quests:
  q=quests[id];quest=json.loads((p/'data/quests.json').read_text())[q]
  variants=[{'condition':{'quest':q,'state':'complete'},'text':'You have done what I asked. Your promised reward has been paid; I will remember your help.'},{'condition':{'quest':q,'state':'active'},'text':'The work is not forgotten. '+quest['text']}]
  options=[choice('I will take the job.','work',{'kind':'accept','quest':q},{'quest':q,'state':'absent'}),choice('What should I look for?','dangers' if q=='bell' else 'materials')]
  if q in ['herbs','iron','charm']:
   options.append(choice('I have brought what you asked for.','work',{'kind':'turn_in','quest':q,'choice':'return'},{'quest':q,'state':'active'}))
   if q=='charm':options.append(choice('I want to keep the charm.','work',{'kind':'turn_in','quest':q,'choice':'keep'},{'quest':q,'state':'active'}))
  if id=='ilya':options.append(choice('What about the three unquiet souls?','elites'))
  options.append(choice('Not right now.','root'))
  nodes['work']={'text':quest['text']+f" I offer {quest['reward']} Crowns and 60 XP.",'variants':variants,'choices':options}
  nodes['materials']={'text':{'iron':'Grave Iron comes from the old guardians and forest creatures. Bring three pieces for the job; upgrades use additional iron.','herbs':'Weeping Herbs grow along the forest paths. Gather three and bring them back. Their pale buds remain visible in the mist.','charm':'The charm lies in a chest in the southwest hollow. You may return it or admit you wish to keep it. My payment is the same; my trust is not.'}.get(q,'Follow the forest road.'),'choices':[choice('I will take the job.','work',{'kind':'accept','quest':q},{'quest':q,'state':'absent'}),choice('Back.','work')]}
 if id=='ilya':nodes['elites']={'text':'The sentinel, the lost hound, and the crypt knight. Lay all three to rest and I will pay 75 Crowns and 60 XP.','variants':[{'condition':{'quest':'elites','state':'complete'},'text':'All three are at peace. Your payment has been made. Thank you.'}],'choices':[choice('I will lay them to rest.','elites',{'kind':'accept','quest':'elites'},{'quest':'elites','state':'absent'}),choice('Back.','work')]}
 if id=='tovin':nodes['root']['variants']=[{'condition':{'memory':'tovin_helped'},'text':'You brought him home, in the only way left to us. I will not forget.'},{'condition':{'memory':'tovin_betrayed'},'text':'You kept the last piece of him. I paid what I promised. Do not ask for my trust.'}]+nodes['root']['variants']
 alltrees[id]={'start':'root','nodes':nodes}
# Contextual greetings use the existing save memory and story flags.
returning={'mara':'Back again? Good. People who return are better customers.','brann':'Still holding that blade? Let us keep it worth holding.','sister':'Welcome back. Tell me where it hurts, or what you have learned.','nell':'Your chair is still warm. What is on your mind?','ilya':'Wanderer. Report when you are ready.','osric':'I hoped you would return. There are words I should have said sooner.','tovin':'You came back. That means more than you think.','vesper':'Another question, another thread. Which will you follow?'}
dangers={'mara':'Keep to the forest road. The east gate needs a sigil. That sentinel has one, if you can persuade it to stop breathing.','brann':'The sentinel wears good iron. The hound in the southwest wears none; it is no less dangerous. Keep your edge ready.','sister':'Three pale herbs grow beside the forest paths. Avoid the green spirits. A blue crystal can cleanse what follows you home.','nell':'Travellers vanished near the southwest hollow. Follow the lamps east, and do not follow any voice calling from the trees.','ilya':'The eastern sentinel carries the crypt sigil. A lost hound haunts the southwest; a knight guards the crypt. Three enemies, three different rhythms.','osric':'The forest dead remember their roads. The crypt dead remember orders. Listen for a pause between them.','tovin':'My brother hid things in a chest in the southwest hollow. The hound is still there. Please be careful.','vesper':'The forest tests your patience. The crypt tests your fear. Bring the sentinel’s sigil east, and let neither test choose for you.'}
bells={'mara':'A very large bell, a very small space to stand safely. Get out of its marked circle. Hit it while it hauls itself upright. Simple advice; expensive to ignore.','brann':'Watch the ground, not its face. Leave the marked circle, wait for the crash, then hit the joints before it recovers.','sister':'You need not endure every blow. Leave the orange circle and let it fall on empty stone. There is time to answer afterward.','nell':'A guest once survived by counting the pause after each toll. Step away first. Let the silence tell you when to strike.','ilya':'Its blast is telegraphed. Clear the circle, keep stamina for a dodge, then counter during recovery. Do not trade blows with it.','osric':'That bell was made to call souls home. Now its keeper mistakes living feet for answers. Leave the circle before it calls.','tovin':'I heard it strike the same patch of stone twice. It cannot follow you through every step. Move when the ground glows.','vesper':'The keeper has mistaken repetition for purpose. Break the pattern: leave its circle, survive the toll, strike the pause.'}
shrines={'mara':'There is a crystal beyond the crypt. If it offers you a fortune, check what it asks in return.','brann':'No hammer I own can cut that shrine’s stone. Whatever waits there, you will need more than a weapon.','sister':'The crystal remembers the first keeper. Go gently. You may find a wound that belongs to you.','nell':'Vesper speaks of a room without a hearth. Take some warmth with you, if only in memory.','ilya':'The shrine lies beyond the Bellkeeper. Once the guardian falls, I cannot follow you. That last report is yours alone.','osric':'The prayer I signed began there. I fear the crystal still knows my handwriting.','tovin':'If the shrine returns your memories, hold them carefully. Even the bad ones are yours.','vesper':'Beyond the guardian, the crystal keeps your first choice. You were the keeper who rang the bell. This time, you may choose otherwise.'}
for id,tree in alltrees.items():
 tree['nodes']['root']['variants'] += [{'condition':{'flag':'ending'},'text':'The shrine has answered. Hollowmere remembers what you have done. '+returning[id]},{'condition':{'memory':id+'_spoken'},'text':returning[id]}]
 tree['nodes']['dangers']['text']=dangers[id];tree['nodes']['bell']['text']=bells[id];tree['nodes']['shrine']['text']=shrines[id]
 tree['nodes']['root']['choices'].insert(-1,choice('I found the forest sigil.','discovery',condition={'flag':'sentinel'}))
 tree['nodes']['discovery']={'text':dangers[id]+' The eastern crypt gate will answer that sigil now.','choices':[choice('What waits below?','bell'),choice('Back.')]}
(p/'data/dialogue_trees.json').write_text(json.dumps(alltrees,indent=2)+'\n')
